INSERT OR REPLACE INTO master_questions (
      id, question_code, certification, question_text, scenario_text,
      question_type, difficulty, options, correct_answer_id, answer_explanation,
      clinical_explanation, "references", exam_tips, common_mistakes, category,
      sub_category, keywords, task_list_version, estimated_time_seconds, tags,
      status, is_premium, is_featured
    ) VALUES (
      'mq-rbt-1787016680398', 'mq-rbt-1787016680398', 'RBT', 'When implementing a DRA procedure for a student who shouts out in class to gain attention, which response should the RBT reinforce?', 'An RBT is assigned to a classroom setting where a student frequently shouts out answers.',
      'scenario_based', 'medium', '[{"id":"A","text":"Quietly raising a hand and waiting to be called on","explanation":"Correct. Raising hand is the functional alternative behavior.","isCorrect":true},{"id":"B","text":"Shouting out the correct answer more quietly","explanation":"Incorrect. Shouting is still the target problem behavior.","isCorrect":false},{"id":"C","text":"Leaving the classroom without permission","explanation":"Incorrect. Non-functional alternative.","isCorrect":false},{"id":"D","text":"Ignoring the teacher for 10 minutes","explanation":"Incorrect. Non-functional alternative.","isCorrect":false}]', 'A', 'DRA involves reinforcing a specific functional alternative behavior while withholding reinforcement for the problem behavior.',
      'Under BACB Task Item D-04, raising a hand serves the same attention function as shouting out, replacing it appropriately.', 'BACB RBT 3rd Edition TCO Item D-04', 'Focus on observable behavior & BACB Task Code D-04.', 'Confusing correlational observations with functional relations.', 'Behavior Reduction',
      'Differential Reinforcement of Alternative Behavior (DRA)', '["Differential Reinforcement of Alternative Behavior (DRA)","RBT","AI Generated","D-04"]', '3rd_edition', 60, '["AI Generated","BACB Item","RBT"]',
      'published', 0, 1
    );

