    ) VALUES (
      'mq-bcba-1786262317738', 'mq-bcba-1786262317738', 'BCBA', 'A client mother offers an RBT a $100 spa gift card at the end of a therapy month. What is the ethical course of action?', 'The RBT is offered a high-value monetary gift card by a client parent.',
      'case_study', 'medium', '[{"id":"A","text":"Accept the gift card graciously","isCorrect":false},{"id":"B","text":"Politely decline, explain BACB ethical guidelines, and notify BCBA supervisor","isCorrect":true},{"id":"C","text":"Accept the gift card but share it with the team","isCorrect":false},{"id":"D","text":"Exchange the gift card for clinical toys","isCorrect":false}]', 'B', 'RBTs must decline high-value monetary gifts to prevent dual relationships.',
      'BACB Ethics Code mandates declining monetary gifts to preserve objective clinical boundaries.', 'BACB Ethics Code Item F-02', NULL, NULL, 'Ethics',
      NULL, '["Ethics","BCBA"]', '3rd_edition', 60, '["CSV Import"]',
      'published', 0, 0
    );

INSERT OR REPLACE INTO master_questions (
      id, question_code, certification, question_text, scenario_text,
