    ) VALUES (
      'mq-rbt-1786262316861', 'mq-rbt-1786262316861', 'RBT', 'A BCBA instructs an RBT to deliver a token every 5 minutes if the learner engages in ZERO instances of vocal screaming. What procedure is this?', 'The learner engages in high-rate vocal screaming during desk work.',
      'scenario_based', 'hard', '[{"id":"A","text":"Differential Reinforcement of Alternative Behavior (DRA)","isCorrect":false},{"id":"B","text":"Differential Reinforcement of Incompatible Behavior (DRI)","isCorrect":false},{"id":"C","text":"Differential Reinforcement of Other Behavior (DRO)","isCorrect":true},{"id":"D","text":"Non-Contingent Reinforcement (NCR)","isCorrect":false}]', 'C', 'DRO reinforces zero occurrences (omission) of target problem behavior during a time interval.',
      'DRO (Omission Training) delivers reinforcement contingent on zero occurrences of the target behavior.', 'BACB RBT 3rd Edition TCO Item D-04', NULL, NULL, 'Behavior Reduction',
      NULL, '["Behavior Reduction","RBT"]', '3rd_edition', 60, '["CSV Import"]',
      'published', 0, 0
    );

