      'mq-rbt-1786262315557', 'mq-rbt-1786262315557', 'RBT', 'An RBT measures the exact time elapsed between presentation of the instruction "Sit down" and when the client initiates sitting. What continuous measurement procedure is being recorded?', 'During a therapy session, the RBT delivers a verbal SD and starts a stopwatch.',
      'scenario_based', 'medium', '[{"id":"A","text":"Duration","isCorrect":false},{"id":"B","text":"Latency","isCorrect":true},{"id":"C","text":"Inter-Response Time (IRT)","isCorrect":false},{"id":"D","text":"Frequency","isCorrect":false}]', 'B', 'Latency measures the elapsed time from SD presentation to response initiation.',
      'Latency measurement tracks response initiation speed relative to environmental prompts.', 'BACB RBT 3rd Edition TCO Item A-01', NULL, NULL, 'Measurement',
      NULL, '["Measurement","RBT"]', '3rd_edition', 60, '["CSV Import"]',
      'published', 0, 0
    );